import{_ as t,o as a,c as r,a4 as d}from"./chunks/framework.C83Ss68L.js";const u=JSON.parse('{"title":"Decision records (ADR)","description":"Numbered records of the decisions that are hard to reverse — context, decision and consequences.","frontmatter":{"title":"Decision records (ADR)","description":"Numbered records of the decisions that are hard to reverse — context, decision and consequences."},"headers":[],"relativePath":"explanation/decisions/index.md","filePath":"explanation/decisions/index.md","lastUpdated":1791568280000}'),o={name:"explanation/decisions/index.md"};function n(s,e,i,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="decision-records-adr" tabindex="-1">Decision records (ADR) <a class="header-anchor" href="#decision-records-adr" aria-label="Permalink to &quot;Decision records (ADR)&quot;">​</a></h1><p>A short numbered record per decision that is hard to reverse: a dependency, a public contract, a piece of the architecture. Each record states the context, the decision and its consequences — good and bad — so that whoever meets the code later (a teammate, your future self, an AI agent) can tell a deliberate choice from an oversight <strong>before</strong> changing it.</p><h2 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h2><ul><li><strong>Status</strong> — <code>Accepted</code>, or <code>Superseded by ADR-XXXX</code>.</li><li><strong>Date</strong> — when the decision shipped (its release).</li><li><strong>Context</strong> — the forces that led to the decision.</li><li><strong>Decision</strong> — what was decided, stated in the present tense.</li><li><strong>Consequences</strong> — what gets better, and what gets worse.</li></ul><p>Approved records are never rewritten. If the team changes its mind, a new record is written and the old one is marked <em>superseded by</em> it — like a new log entry that does not cross out the previous one. Nothing here is an implementation detail: the <a href="/katanakit-js/guides/architecture">Architecture</a> page and the <a href="/katanakit-js/api/">API Reference</a> cover those.</p><h2 id="records" tabindex="-1">Records <a class="header-anchor" href="#records" aria-label="Permalink to &quot;Records&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Decision</th><th>Status</th><th>Date</th></tr></thead><tbody><tr><td><a href="/katanakit-js/explanation/decisions/adr-0001-safe-results">ADR-0001</a></td><td>Safe Results instead of exceptions</td><td>Accepted</td><td>2026-09-26</td></tr><tr><td><a href="/katanakit-js/explanation/decisions/adr-0002-singleton-facades">ADR-0002</a></td><td>Singleton facades exposed as <code>use*</code> functions</td><td>Accepted</td><td>2026-10-04</td></tr><tr><td><a href="/katanakit-js/explanation/decisions/adr-0003-adapter-subpath-exports">ADR-0003</a></td><td>Framework adapters only on subpath exports</td><td>Accepted</td><td>2026-09-20</td></tr><tr><td><a href="/katanakit-js/explanation/decisions/adr-0004-hexagonal-core">ADR-0004</a></td><td>Hexagonal layout with a pure core</td><td>Accepted</td><td>2026-09-03</td></tr><tr><td><a href="/katanakit-js/explanation/decisions/adr-0005-docs-as-code">ADR-0005</a></td><td>Docs as code: generated reference, four page kinds</td><td>Accepted</td><td>2026-09-26</td></tr></tbody></table><h2 id="adding-a-record" tabindex="-1">Adding a record <a class="header-anchor" href="#adding-a-record" aria-label="Permalink to &quot;Adding a record&quot;">​</a></h2><p>Copy the shape of an existing record, number it sequentially and open it in the same pull request as the change it describes. The <a href="https://github.com/senseikatana/katanakit-js/blob/dev/CONTRIBUTING.md" target="_blank" rel="noreferrer">contributing contract</a> lists what counts as a decision: a new runtime dependency, a public contract change, an architecture move.</p>',9)])])}const f=t(o,[["render",n]]);export{u as __pageData,f as default};
